#include "vulkan_pipeline.hpp"
#include <fstream>

namespace qds {
VulkanPipeline::~VulkanPipeline(){ auto d=context_.device(); if(decode_pipeline_)vkDestroyPipeline(d,decode_pipeline_,nullptr); if(layout_)vkDestroyPipelineLayout(d,layout_,nullptr); if(descriptors_)vkDestroyDescriptorSetLayout(d,descriptors_,nullptr); if(descriptor_pool_)vkDestroyDescriptorPool(d,descriptor_pool_,nullptr); }
VkShaderModule VulkanPipeline::load_shader(const std::filesystem::path& p,std::string& e){ std::ifstream f(p,std::ios::binary|std::ios::ate); if(!f){e="missing shader: "+p.string();return{};} auto n=f.tellg(); if(n<=0||n%4){e="invalid SPIR-V: "+p.string();return{};} std::vector<std::uint32_t>b(static_cast<size_t>(n)/4);f.seekg(0);f.read(reinterpret_cast<char*>(b.data()),n); VkShaderModuleCreateInfo ci{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};ci.codeSize=static_cast<size_t>(n);ci.pCode=b.data();VkShaderModule m{};if(vkCreateShaderModule(context_.device(),&ci,nullptr,&m)!=VK_SUCCESS){e="vkCreateShaderModule failed";return{};}return m; }
bool VulkanPipeline::initialize(const std::filesystem::path& dir,std::string& e){ std::vector<VkDescriptorSetLayoutBinding>b(3);for(std::uint32_t i=0;i<3;i++){b[i].binding=i;b[i].descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;b[i].descriptorCount=1;b[i].stageFlags=VK_SHADER_STAGE_COMPUTE_BIT;}VkDescriptorSetLayoutCreateInfo dl{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};dl.bindingCount=3;dl.pBindings=b.data();if(vkCreateDescriptorSetLayout(context_.device(),&dl,nullptr,&descriptors_)!=VK_SUCCESS){e="descriptor layout failed";return false;}VkPipelineLayoutCreateInfo pl{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};pl.setLayoutCount=1;pl.pSetLayouts=&descriptors_;if(vkCreatePipelineLayout(context_.device(),&pl,nullptr,&layout_)!=VK_SUCCESS){e="pipeline layout failed";return false;}auto shader=load_shader(dir/"packet_decode.comp.spv",e);if(!shader)return false;VkPipelineShaderStageCreateInfo stage{VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO};stage.stage=VK_SHADER_STAGE_COMPUTE_BIT;stage.module=shader;stage.pName="main";VkComputePipelineCreateInfo cp{VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO};cp.stage=stage;cp.layout=layout_;auto ok=vkCreateComputePipelines(context_.device(),VK_NULL_HANDLE,1,&cp,nullptr,&decode_pipeline_)==VK_SUCCESS;vkDestroyShaderModule(context_.device(),shader,nullptr);if(!ok){e="decode pipeline failed";}return ok; }
std::uint32_t VulkanPipeline::memory_type(std::uint32_t bits,VkMemoryPropertyFlags p)const{VkPhysicalDeviceMemoryProperties m{};vkGetPhysicalDeviceMemoryProperties(context_.physical_device(),&m);for(std::uint32_t i=0;i<m.memoryTypeCount;i++)if((bits&(1u<<i))&&(m.memoryTypes[i].propertyFlags&p)==p)return i;return UINT32_MAX;}
bool VulkanPipeline::create_buffer(VkDeviceSize s,VkBufferUsageFlags u,VkMemoryPropertyFlags p,VulkanBuffer&o,std::string&e){VkBufferCreateInfo ci{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};ci.size=s;ci.usage=u;ci.sharingMode=VK_SHARING_MODE_EXCLUSIVE;if(vkCreateBuffer(context_.device(),&ci,nullptr,&o.buffer)!=VK_SUCCESS){e="buffer create failed";return false;}VkMemoryRequirements r{};vkGetBufferMemoryRequirements(context_.device(),o.buffer,&r);auto type=memory_type(r.memoryTypeBits,p);if(type==UINT32_MAX){e="no matching memory type";destroy_buffer(o);return false;}VkMemoryAllocateInfo a{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};a.allocationSize=r.size;a.memoryTypeIndex=type;if(vkAllocateMemory(context_.device(),&a,nullptr,&o.memory)!=VK_SUCCESS){e="memory allocation failed";destroy_buffer(o);return false;}vkBindBufferMemory(context_.device(),o.buffer,o.memory,0);o.size=s;return true;}
void VulkanPipeline::destroy_buffer(VulkanBuffer&b){auto d=context_.device();if(b.buffer)vkDestroyBuffer(d,b.buffer,nullptr);if(b.memory)vkFreeMemory(d,b.memory,nullptr);b={};}
}
